    const dwarves = makeCard({
      name: 'Seven Dwarves',
      oracle_text: 'A deck can have up to seven cards named Seven Dwarves.',
    });
    assert.strictEqual(singletonLimit(dwarves), 7);
    const nazgul = makeCard({
      name: 'Nazgûl',
      oracle_text: 'A deck can have up to nine cards named Nazgûl.',
    });
    assert.strictEqual(singletonLimit(nazgul), 9);
    const plainDigit = makeCard({
      name: 'Test Card',
      oracle_text: 'A deck can have up to 7 cards named Test Card.',
    });
    assert.strictEqual(singletonLimit(plainDigit), 7);
    const plainDigitEight = makeCard({
      name: 'Test Card 2',
      oracle_text: 'A deck can have up to 12 cards named Test Card 2.',
    });
    assert.strictEqual(singletonLimit(plainDigitEight), 12);
  });

